package com.abdickers.realms;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import androidx.core.content.FileProvider;
import java.io.*;
import java.nio.charset.StandardCharsets;

public final class SetupActivity extends Activity {
 private static final int PICK=717;
 @Override protected void onCreate(Bundle state){super.onCreate(state);if(state!=null){finish();return;}if(getIntent().getBooleanExtra("prepare",false))prepare();else startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),PICK);}
 private void prepare(){try{File dir=new File(getCacheDir(),"setup");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();org.json.JSONObject request=NativeSetup.request(this);String phoneCode=request.getString("recipientSha256").substring(0,12);File file=new File(dir,"Command-Work-Setup-Request.json");try(FileOutputStream out=new FileOutputStream(file)){out.write(request.toString(2).getBytes(StandardCharsets.UTF_8));}Uri uri=FileProvider.getUriForFile(this,getPackageName()+".files",file);new AlertDialog.Builder(this).setTitle("Secure Work setup request").setMessage("Phone code: "+phoneCode+"\n\nShare this request file so connections can be encrypted specifically for this phone. It contains a public key and one-time request ID, not passwords, API tokens, mail, or your private key. It expires in 24 hours.\n\nImport the encrypted reply here when it is ready.").setPositiveButton("Share request",(d,w)->{startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share the public setup request"));finish();}).setNegativeButton("Cancel",(d,w)->finish()).setOnCancelListener(d->finish()).show();}catch(Exception e){failed("Could not prepare this phone’s setup request.");}}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=PICK)return;if(result!=RESULT_OK||intent==null||intent.getData()==null){finish();return;}try(InputStream in=getContentResolver().openInputStream(intent.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] buffer=new byte[4096];int size;while((size=in.read(buffer))!=-1){if(out.size()+size>65536)throw new IOException();out.write(buffer,0,size);}NativeSetup.Preview preview=NativeSetup.preview(this,out.toString(StandardCharsets.UTF_8.name()));String providers=String.join(", ",preview.credentials().keySet());new AlertDialog.Builder(this).setTitle("Import Work connections").setMessage("Verified publisher signature and this phone’s private key.\n\nConnections: "+providers+"\n\nThese credentials will be encrypted in Android Keystore. No feed is read until you press Refresh.").setPositiveButton("Import",(d,w)->{try{NativeSetup.install(this,preview);new AlertDialog.Builder(this).setMessage("Work connections imported. Select a panel and tap Refresh.").setPositiveButton("Done",(a,b)->finish()).show();}catch(Exception e){failed("Could not install this setup. Request a fresh encrypted reply.");}}).setNegativeButton("Cancel",(d,w)->finish()).setOnCancelListener(d->finish()).show();}catch(Exception e){failed("Could not verify this setup. It may be expired, altered, already used, or prepared for another phone.");}}
 private void failed(String message){new AlertDialog.Builder(this).setMessage(message).setPositiveButton("Close",(d,w)->finish()).setOnCancelListener(d->finish()).show();}
}
